// GENERATED by scripts/build-io.mjs from src/ - edit the source, not this file.
// Follow-up suggestions shown under a product carousel.
//
// Built on the client from what the carousel actually carried - the product
// names - so they always fit the products on screen. Nothing about price: a
// "cheaper than X" button promises products the catalog may not have. Each label is
// also the message that gets sent, so the agent receives plain, specific text.
import type { ChatProduct } from './mapMessage';

const MAX_SUGGESTIONS = 4;

interface Category {
  key: string;
  /** "Mais opções de <plural>". */
  plural: string;
  /** Accessories have no residential/professional split worth offering. */
  accessory?: boolean;
}

// Matched against the start of the product name, after normalising accents.
const CATEGORIES: Array<{ pattern: RegExp } & Category> = [
  { pattern: /^lavadora de piso|^limpadora/, key: 'piso', plural: 'limpadoras de piso' },
  { pattern: /^lavadora/, key: 'lavadora', plural: 'lavadoras' },
  { pattern: /^aspirador(a)? robo|^robo/, key: 'robo', plural: 'robôs aspiradores' },
  { pattern: /^aspirador/, key: 'aspirador', plural: 'aspiradores' },
  { pattern: /^extratora/, key: 'extratora', plural: 'extratoras' },
  { pattern: /^vassoura/, key: 'vassoura', plural: 'vassouras elétricas' },
  { pattern: /^(limpador|lavadora) de (janela|vidro)|^limpa ?vidro/, key: 'vidro', plural: 'limpadores de vidro' },
  { pattern: /^(vaporizador|limpadora a vapor)/, key: 'vapor', plural: 'limpadoras a vapor' },
  {
    pattern: /^(aplicador|bico|mangueira|filtro|kit|detergente|escova|lanca|pistola|adaptador|acessorio|refil|saco)/,
    key: 'acessorio',
    plural: 'acessórios',
    accessory: true,
  },
];

const PROFESSIONAL = /\b(profissional|professional|industrial|hds?|nt|br|bd|puzzi)\b/i;

/** Kärcher model codes: K5, K2 Plus, WD 3, SC 4, FC 7, VC 4... */
const MODEL =
  /\b([A-Z]{1,3})\s?(\d{1,2})(?:\s(Plus|Power|Premium|Compact|Classic|Control|Full|Smart|Basic|Car))?\b/;

function normalise(text: string): string {
  return text
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .trim();
}

function categoryOf(name: string): Category | null {
  const clean = normalise(name);
  return CATEGORIES.find((c) => c.pattern.test(clean)) ?? null;
}

/** The category most of the carousel belongs to, if one stands out. */
function dominantCategory(products: ChatProduct[]): Category | null {
  const counts = new Map<string, { category: Category; n: number }>();
  for (const product of products) {
    const category = categoryOf(product.name);
    if (!category) continue;
    const entry = counts.get(category.key) ?? { category, n: 0 };
    entry.n += 1;
    counts.set(category.key, entry);
  }
  let best: { category: Category; n: number } | null = null;
  // for-of over a real array: an iterator here could break under a loose transpile.
  for (const entry of Array.from(counts.values())) if (!best || entry.n > best.n) best = entry;
  return best && best.n * 2 >= products.length ? best.category : null;
}

function modelOf(name: string): string | null {
  const match = name.match(MODEL);
  if (!match) return null;
  const [, letters, digits, variant] = match;
  // "K5" reads as Kärcher writes it; two-letter lines keep the space ("WD 3").
  const code = letters.length === 1 ? `${letters}${digits}` : `${letters} ${digits}`;
  return variant ? `${code} ${variant}` : code;
}

export function suggestFollowUps(products: ChatProduct[]): string[] {
  if (!products.length) return [];
  const suggestions: string[] = [];
  const category = dominantCategory(products);

  suggestions.push(category ? `Mais opções de ${category.plural}` : 'Mais opções');

  if (!category?.accessory) {
    const professional = products.some((p) => PROFESSIONAL.test(p.name));
    suggestions.push(professional ? 'Alternativa para uso residencial' : 'Alternativa para uso profissional');
  }

  const models = Array.from(new Set(products.map((p) => modelOf(p.name)).filter((m): m is string => Boolean(m))));
  if (models.length >= 2) suggestions.push(`Comparar ${models[0]} e ${models[1]}`);
  else if (models.length === 1 && category?.key === 'lavadora') suggestions.push(`Acessórios para a ${models[0]}`);
  else if (category && !category.accessory) suggestions.push(`Acessórios para ${category.plural}`);

  return suggestions.slice(0, MAX_SUGGESTIONS);
}
